import{_ as o,o as a,c as d,a3 as i}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"基础篇 3：小程序架构及其实现机制","description":"","frontmatter":{},"headers":[],"relativePath":"books/wechat-miniprogram/04-基础篇-3-小程序架构及其实现机制.md","filePath":"books/wechat-miniprogram/04-基础篇-3-小程序架构及其实现机制.md","lastUpdated":1781445373000}'),c={name:"books/wechat-miniprogram/04-基础篇-3-小程序架构及其实现机制.md"};function p(t,e,s,r,l,n){return a(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="基础篇-3-小程序架构及其实现机制" tabindex="-1">基础篇 3：小程序架构及其实现机制 <a class="header-anchor" href="#基础篇-3-小程序架构及其实现机制" aria-label="Permalink to &quot;基础篇 3：小程序架构及其实现机制&quot;">​</a></h1><h2 id="小程序-vs-html5" tabindex="-1">小程序 VS HTML5 <a class="header-anchor" href="#小程序-vs-html5" aria-label="Permalink to &quot;小程序 VS HTML5&quot;">​</a></h2><p>小程序并不是 HTML5 应用，而是更偏向于传统的 CS 架构，它是基于<strong>数据驱动</strong>的模式，一切皆组件（视图组件）。下面是小程序与普通 Web App 的对比。</p><ul><li>普通 HTML5 都是执行在浏览器的宿主环境，浏览器提供 <code>window</code>、<code>document</code> 等 BOM 对象，但小程序没有 <code>window</code>、<code>document</code>，它更像是一个类似 Node.js 的宿主环境；因此在小程序内不能使用 <code>document.querySelector</code> 这类 DOM 选择器，也不支持 <code>XMLHttpRequest</code>、<code>location</code>、<code>localStorage</code> 等这些浏览器提供的 API，只能使用小程序自己实现的 API</li><li>小程序并非是直接通过 URL 访问的，而是通过信道服务进行通信和会话管理，所以它不支持 Cookie 存储，同时访问资源使用 <code>wx.request</code> 则不存在跨域的问题</li><li>小程序在 JavaScript 的模块化上支持 CommonJS，通过 require 加载，跟 Node.js 类似</li><li>小程序的页面样式完全继承了 CSS 的语法，但是在选择器上面会少一些，布局支持 flex 布局</li><li>小程序的整体框架采用面向状态编程方式，状态管理从 API 来看采用类似 Redux 的设计方式；单向数据绑定方式，当 View 在 Action 操作后，只能通过 Action 的业务处理来更新 View</li></ul><p>页面组件模块上，WXML 提供了一整套的「自定义 UI 组件标签」，有些组件实际是 HTML5 实现的，有些组件为了解决权限、性能和适配等问题实际是 Native 实现的（如 map、input、canvas、video）。</p><p>笔者在 Android 手机上通过「设置 -&gt; 开发人员选项 -&gt; 显示布局界限」选择<strong>显示布局界限</strong>之后，打开小程序的页面会看到 Native 的边框，如果是 Native 组件则会展现出来，下面是今日头条小程序的截图。</p><div style="margin:20px auto;text-align:center;"><img src="https://user-gold-cdn.xitu.io/2018/8/13/165313734e6618f3?w=1079&amp;h=1920&amp;f=jpeg&amp;s=371788" width="360"></div><p>而使用 <a href="https://x5.tencent.com/" target="_blank" rel="noreferrer">X5 内核</a>的 inspect 版本（X5 内核 debug 功能在 <a href="https://juejin.im/book/5b70f101e51d456669381803/section/5b70f888f265da27e36ef112" target="_blank" rel="noreferrer">12 节真机调试技巧</a>部分有详细介绍），打开 Chrome 的远程调试，看到当前页面如下图所示。</p><p><img src="https://user-gold-cdn.xitu.io/2018/8/13/165313705cbd8524?w=960&amp;h=889&amp;f=png&amp;s=507229" alt="" loading="lazy"></p><p>从图中看到，今日头条的小程序顶部导航区域是 Native 组件（会显示布局界限），而底部没有边框，在 Chrome 内发现实际为 webview 的页面实现。</p><h2 id="小程序架构解密" tabindex="-1">小程序架构解密 <a class="header-anchor" href="#小程序架构解密" aria-label="Permalink to &quot;小程序架构解密&quot;">​</a></h2><p><img src="https://user-gold-cdn.xitu.io/2018/8/13/16531377b0ecbfc4?w=1024&amp;h=768&amp;f=jpeg&amp;s=270403" alt="" loading="lazy"></p><p>小程序架构如上图所示，分为视图层和逻辑层，视图层是在 WebView 内渲染，逻辑层则有 JavaScriptCore 来渲染；其中视图层可以多个（考虑到整体性能，最多可以 5 个），逻辑层则全局只有一个（实际通过开启 X5 内核另起一个 JavascriptCore 线程）。</p><p>视图层是 WebView，逻辑层为 JavaScriptCore，证据如下：使用 Android 手机，开启 X5 内核 debug 之后，在 Chrome inspect 中可以看到下图所示的内容。</p><p><img src="https://user-gold-cdn.xitu.io/2018/8/13/1653137a557f6bbc?w=927&amp;h=439&amp;f=png&amp;s=87662" alt="" loading="lazy"></p><p>在小程序内，视图层负责页面渲染，逻辑层负责逻辑处理、全局状态管理、请求和接口调用。逻辑层在小程序中称为 <code>APP Service</code>，视图层称为 <code>View</code>。</p><p>逻辑层和视图层通过微信的 <code>JSBridge</code> 来实现通信的，逻辑层数据变化通过 <code>JSBridge</code> 通知视图层，触发视图层更新；当视图层触发事件，则继续通过 <code>JSBridge</code> 将事件通知到逻辑层做处理，如此交互进行。</p><p><code>JSBridge</code> 在三个环境（开发者工具、iOS 和 Android）中实现机制不同，在调用 Native 能力时主要使用 <code>invokeHandler</code>：</p><ul><li>开发者工具：通过 <code>window.postMessage</code> 来封装</li><li>iOS：通过 WKWebview 的 <code>window.webkit.messageHandlers.invokeHandler.postMessage</code></li><li>Android：通过 <code>WeixinJSCore.invokeHandler</code></li></ul><p>在消息分发的时候，则使用 <code>publishHandler</code>：</p><ul><li>开发者工具：通过 <code>addEventListener(&#39;message&#39;)</code> 来监听消息，然后处理分发</li><li>iOS：使用 WKWebview 的 <code>window.webkit.messageHandlers.publishHandler.postMessage</code></li><li>Android：通过 <code>WeixinJSCore.publishHandler</code></li></ul><p>其中，Android 的 <code>WeixinJSCore</code> 是 X5 内核暴露出来的对象，其作为 <code>window</code> 对象的一个属性，提供一些供 JavaScript 调用的能力。</p><p>这部分可以在开发者工具或者 X5 内核 debug 模式下，找到 <code>WAService.js</code>（代码笔者放到了<a href="https://gist.github.com/ksky521/590fdffcff203ee9fa83cb188b4a664b" target="_blank" rel="noreferrer">这个 Gist</a> 上，方便大家查看） 看到：</p><p>WeixinJSBridge 提供的方法有 <code>invoke</code>、<code>publish</code> 和 <code>subscribe</code> 等，<code>invoke</code> 就是关键的调用 Native 端能力的方法，<code>publish</code> 是消息分发的方法。注意下图的 <code>invoke</code> 实际是来自<code>y</code>，<code>publish</code> 来自 <code>w</code>，<code>e</code> 为 <code>window</code>。</p><p><img src="https://user-gold-cdn.xitu.io/2018/8/23/16565a664eee46a3?w=457&amp;h=619&amp;f=png&amp;s=70984" alt="" loading="lazy"></p><p><code>y</code> 的实现最后调用了<code>g</code>，<code>w</code> 的实现最后调用了<code>_</code>。</p><p><img src="https://user-gold-cdn.xitu.io/2018/8/23/16565a9a64c86a08?w=392&amp;h=440&amp;f=png&amp;s=56038" alt="" loading="lazy"></p><p>继续查找<code>g</code>、<code>_</code> 的实现，发现 <code>g</code>、<code>_</code> 最后都调用了 <code>d</code> 和 <code>f</code> 的方法（显现了关键字<code>invokeHandler</code>、<code>publishHandler</code>）。</p><p><img src="https://user-gold-cdn.xitu.io/2018/8/23/16565aad2c8758ef?w=827&amp;h=462&amp;f=png&amp;s=71454" alt="" loading="lazy"></p><p>继续查找，发现 <code>d</code> 和 <code>f</code> 分别是来自 <code>window.webkit</code>、<code>window.WeixinJSCore</code>。</p><p><img src="https://user-gold-cdn.xitu.io/2018/8/23/16565ad03ce850c6?w=257&amp;h=82&amp;f=png&amp;s=12861" alt="" loading="lazy"></p><p>因为在一个小程序中可以打开多个视图层（webview），要保证发送的消息准确送到每个具体的 webview 中，需要通过每个 webview 唯一标识 <code>webviewId</code> 来实现。发送消息时，携带 <code>webviewId</code>，然后逻辑层处理完对应的逻辑，如果需要通知或者执行对应 webview 的代码，则可以通过 <code>webviewId</code> 找到对应的 webview，下发通知。</p><h2 id="小程序生命周期" tabindex="-1">小程序生命周期 <a class="header-anchor" href="#小程序生命周期" aria-label="Permalink to &quot;小程序生命周期&quot;">​</a></h2><p>小程序生命周期包括应用的生命周期（逻辑层 App Service）和页面的生命周期（视图层 View），两者支持的事件不同，详见官方文档中的这张配图。</p><div style="margin:20px auto;text-align:center;"><img src="https://user-gold-cdn.xitu.io/2018/8/13/16531394a3c8fe1f?w=662&amp;h=1014&amp;f=png&amp;s=45267" width="540"></div><p>掌握了上面小程序实现原理的内容，再来看小程序的生命周期就很好理解了。</p><p>小程序启动时，会同时启动两个线程，一个负责页面渲染的 WebView（实际不止一个，后面讲解），一个负责逻辑的 JavaScriptCore。逻辑层初始化后会将初始化数据（app.js 中的 global data）通过 JSBridge 传递给渲染层进行渲染，渲染层 WebView 页面渲染完之后又会跟逻辑层通信。</p><p>理解了小程序架构和启动流程，小程序整个生命周期的流程只需要对着上面的流程图就可以很容易理解。</p><h2 id="小程序为什么感觉快" tabindex="-1">小程序为什么感觉快 <a class="header-anchor" href="#小程序为什么感觉快" aria-label="Permalink to &quot;小程序为什么感觉快&quot;">​</a></h2><p>小程序在体验上不仅仅页面流畅，而且点击之后，页面跳转也会比普通的 HTML5 要快很多，这是因为小程序的视图层做了预加载处理。下图是通过 X5 内核开启 inspect 版本之后，在 Chrome 中看到的手机 WebView 的页面情况。小程序选择今日头条，打开了两个页面（热点新闻列表和某条新闻详情），但实际在 Chrome 中看到的 WebView 页面总是比真实打开的页面要多一个，这个多出来的隐藏 WebView 就是提前初始化预热的，方便打开下一个小程序页面来使用，这样就节省了 WebView 初始化的时间，从而大幅提升了跳页效率。</p><p><img src="https://user-gold-cdn.xitu.io/2018/8/13/16531399500bca20?w=1433&amp;h=760&amp;f=jpeg&amp;s=228402" alt="" loading="lazy"></p><h2 id="小程序-wxml-是怎么转成-html-的" tabindex="-1">小程序 WXML 是怎么转成 HTML 的 <a class="header-anchor" href="#小程序-wxml-是怎么转成-html-的" aria-label="Permalink to &quot;小程序 WXML 是怎么转成 HTML 的&quot;">​</a></h2><p>小程序的视图层最终是渲染在一个 webview 中的，通过下图就可以看到我们在 WXML 中写的 <code>view</code>、<code>icon</code>、<code>text</code> 等标签最终会转换成 <code>wx-*</code> 等标签。</p><p><img src="https://user-gold-cdn.xitu.io/2018/8/13/1653139d01fde2a4?w=1127&amp;h=877&amp;f=png&amp;s=436706" alt="" loading="lazy"></p><p>那么 WXML 到 HTML 的过程发生了什么呢？</p><p>首先，WXML 写完之后经过编译工具 <code>wcc</code> 转成可执行的 JS，下面的命令可以将某个页面转为 JS：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index.wxml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index.js</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><blockquote><p><strong>TIPS：</strong> <code>wcc</code> 和 <code>wcsc</code> 是小程序的 WXML 和 WXSS 的编译工具，是二进制文件，在 macOS 中可以在<code>/Applications/wechatwebdevtools.app/Contents/Resources/package.nw/js/vendor/</code> 路径中找到（应用 → 右键微信开发者工具 → 查看包文件）</p></blockquote><p><img src="https://user-gold-cdn.xitu.io/2018/8/13/165313e0a87d209f?w=1764&amp;h=1096&amp;f=png&amp;s=413336" alt="" loading="lazy"></p><p>这个 JS 里面有个重要的函数是 <code>$gwx</code>：</p><p><img src="https://user-gold-cdn.xitu.io/2018/8/13/165313e2c44a689c?w=981&amp;h=392&amp;f=png&amp;s=248171" alt="" loading="lazy"></p><p>这个 JS 主要接收一个 <code>path</code> 将 <code>path</code> 的页面转换成一个 Virtual DOM：</p><p><img src="https://user-gold-cdn.xitu.io/2018/8/13/165313e4c84b0937?w=341&amp;h=455&amp;f=png&amp;s=44563" alt="" loading="lazy"></p><p>在这个 VDOM 结构里面就会找到以<code>wx-*</code> 开头的 tag，有了这个 VDOM 结构，就可以使用对应的 tag 创建 HTML 片段了。</p><p>整个流程梳理如下：</p><p><img src="https://user-gold-cdn.xitu.io/2018/8/13/165313e72ea7a43a?w=794&amp;h=97&amp;f=png&amp;s=26808" alt="" loading="lazy"></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>本节重点介绍了小程序和普通的 HTML5 有什么区别，从小程序底层机制上来说明小程序是如何最终展现在 WebView 界面上的。本节涉及较多的源码和反编译技巧，对于初学者来说只需要了解微信小程序由逻辑层和视图层两个不同的线程进行交互而形成，而视图层是通过将 WXML 转换成 JS，最终由 JS 生成 HTML 片段放在 WebView 中显示的。</p>',58)])])}const g=o(c,[["render",p]]);export{m as __pageData,g as default};
